<?php require_once __DIR__.'/../includes/functions.php';require_role(['admin','finance','production']);$rows=db()->query("SELECT o.*,u.name customer FROM orders o JOIN customers c ON c.id=o.customer_id JOIN users u ON u.id=c.user_id ORDER BY o.created_at DESC")->fetchAll();?><!doctype html><html lang="id"><head><?php include __DIR__.'/../includes/head.php';?></head><body><?php include __DIR__.'/../includes/header.php';?><main class="content"><h1>Orders</h1><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['order_number'])?></td><td><?=e($r['customer'])?></td><td>Rp <?=number_format($r['total_amount'],0,',','.')?></td><td><span class="badge"><?=e($r['status'])?></span></td></tr><?php endforeach;?></table></div></main></body></html>